pub(crate) fn definition_bounds(line: &str) -> Option<(usize, usize)> {
    let trimmed = line.trim();
    let rest = trimmed.strip_prefix('[')?;
    if rest.starts_with('`') {
        return None;
    }
    let close = rest.find(']')?;
    if !rest[close + 1..].trim_start().starts_with(':') {
        return None;
    }
    let untrimmed = &rest[..close];
    let key = untrimmed.trim();
    if key.is_empty() {
        return None;
    }
    let start =
        line.len() - line.trim_start().len() + 1 + untrimmed.len() - untrimmed.trim_start().len();
    Some((start, start + key.len()))
}

